insert into public.people (id, slug, first_name, last_name, nickname, aliases, bio, legend, category, tags, first_seen, status) values
  (md5('person:marek')::uuid, 'marek', 'Marek', null, 'Szef', '{}'::text[], 'Znany głównie z tego, że zawsze wie, gdzie wszyscy są.', 'Legenda głosi, że zna każdego kierowcę autobusu w mieście po imieniu.', 'stala-ekipa', array['Czechowice']::text[], 2014, 'published'),
  (md5('person:krzychu')::uuid, 'krzychu', 'Krzychu', null, 'Turbo', '{}'::text[], 'Pierwszy na miejscu, ostatni do wyjścia.', 'Legenda głosi, że kiedyś przyszedł na imprezę dzień wcześniej i nikt nie zauważył różnicy.', 'legenda', array['Czechowice']::text[], 2013, 'published'),
  (md5('person:krzysiek')::uuid, 'krzysiek', 'Krzysiek', null, 'Mały', array['Krzysio']::text[], 'Mierzy prawie dwa metry. Stąd ksywka.', null, 'bywalec', array['Czechowice']::text[], 2016, 'published'),
  (md5('person:krzysztof')::uuid, 'krzysztof', 'Krzysztof', null, 'Profesor', '{}'::text[], 'Mówi pełnymi zdaniami i nosi okulary, więc jest Profesorem.', 'Podobno ma w domu mapę osiedla z zaznaczonymi wszystkimi ławkami.', 'z-daleka', array['Czechowice']::text[], 2018, 'published'),
  (md5('person:lysy')::uuid, 'lysy', 'Łysy', null, 'Łysy', array['Lysy', 'Mirek']::text[], 'Łysy od liceum. Z wyboru, jak twierdzi.', 'Legenda głosi, że w 2016 roku jeszcze miał grzywkę. Są na to dwa zdjęcia.', 'legenda', array['Czechowice']::text[], 2012, 'published'),
  (md5('person:bartek')::uuid, 'bartek', 'Bartek', null, 'Bartas', '{}'::text[], 'Najspokojniejszy człowiek w ekipie. Do czasu.', null, 'stala-ekipa', array['Czechowice']::text[], 2014, 'published'),
  (md5('person:arek')::uuid, 'arek', 'Arek', null, 'Arczi', '{}'::text[], 'Specjalista od akcji, które „miały być na chwilę”.', 'Legenda głosi, że był na stacji o 3:00 w nocy częściej niż jej pracownicy.', 'stala-ekipa', array['Czechowice']::text[], 2015, 'published'),
  (md5('person:damian')::uuid, 'damian', 'Damian', null, 'Dziki', '{}'::text[], 'Energia na poziomie 140%. Zawsze.', null, 'bywalec', array['Czechowice']::text[], 2017, 'published'),
  (md5('person:seba')::uuid, 'seba', 'Seba', null, 'Seba', array['Sebastian']::text[], 'Człowiek-głośnik. Zawsze ma muzykę.', null, 'bywalec', array['Czechowice']::text[], 2016, 'published'),
  (md5('person:kamil')::uuid, 'kamil', 'Kamil', null, 'Kamyk', '{}'::text[], 'Bramkarz. Na boisku i w życiu nic nie przepuści.', null, 'stala-ekipa', array['Czechowice']::text[], 2015, 'published'),
  (md5('person:tomek')::uuid, 'tomek', 'Tomek', null, 'Tomi', '{}'::text[], 'Pracuje ze wszystkimi. W różnych firmach. Jednocześnie.', null, 'bywalec', array['Czechowice']::text[], 2017, 'published'),
  (md5('person:mariusz')::uuid, 'mariusz', 'Mariusz', null, 'Pudzian', '{}'::text[], 'Siłownia to jego drugi dom. Pierwszy to ławka pod blokiem.', null, 'bywalec', array['Czechowice']::text[], 2016, 'published'),
  (md5('person:grzesiu')::uuid, 'grzesiu', 'Grzesiu', null, 'Grzybek', array['Grzegorz']::text[], 'Zbiera grzyby, historie i drobne na bilet.', null, 'z-daleka', array['Czechowice']::text[], 2019, 'published'),
  (md5('person:zbyszek')::uuid, 'zbyszek', 'Zbyszek', null, 'Wujek', '{}'::text[], 'Niczyj wujek, ale wszyscy tak mówią.', 'Legenda głosi, że pamięta czasy, gdy na rynku była fontanna. Albo że jej nie było.', 'legenda', array['Czechowice']::text[], 2010, 'published'),
  (md5('person:kuba')::uuid, 'kuba', 'Kuba', null, 'Kubson', '{}'::text[], 'Młodszy brat Bartka. Wszędzie chodził za starszymi.', null, 'bywalec', array['Czechowice']::text[], 2018, 'published'),
  (md5('person:rafal')::uuid, 'rafal', 'Rafał', null, 'Rafi', '{}'::text[], 'Znany z tego, że zawsze ma „jeszcze jedną sprawę do załatwienia”.', null, 'z-daleka', array['Czechowice']::text[], 2020, 'published'),
  (md5('person:ewka')::uuid, 'ewka', 'Ewka', null, 'Szefowa', '{}'::text[], 'Jedyna osoba, której słucha Marek.', null, 'stala-ekipa', array['Czechowice']::text[], 2015, 'published'),
  (md5('person:magda')::uuid, 'magda', 'Magda', null, 'Madzia', '{}'::text[], 'Siostra Damiana. Zdecydowanie ta rozsądniejsza.', null, 'bywalec', array['Czechowice']::text[], 2017, 'published'),
  (md5('person:dawid')::uuid, 'dawid', 'Dawid', null, 'Cichy', '{}'::text[], 'Nic nie mówi, wszystko widzi.', 'Podobno do dziś trzyma paragon z tamtej nocy.', 'z-daleka', array['Czechowice']::text[], 2021, 'published'),
  (md5('person:darek')::uuid, 'darek', 'Darek', null, 'Sąsiad', '{}'::text[], 'Mieszka za ścianą Marka i wie o wszystkim pierwszy.', null, 'bywalec', array['Czechowice']::text[], 2016, 'published')
