  (md5('relationship:kamil-tomek')::uuid, 'kamil-tomek', md5('person:kamil')::uuid, md5('person:tomek')::uuid, 'praca', 50, 2019, null, 'Jedna zmiana w hurtowni. Kamil łapał, Tomek rzucał.', 'neutralna', 'confirmed', 'personal', null, 'published'),
