  (md5('relationship:zbyszek-krzysztof')::uuid, 'zbyszek-krzysztof', md5('person:zbyszek')::uuid, md5('person:krzysztof')::uuid, 'znajomi', 50, 2018, null, 'Długie rozmowy o historii miasta przy sklepie na rogu.', 'pozytywna', 'confirmed', 'personal', md5('location:Sklep na rogu')::uuid, 'published'),
  (md5('relationship:zbyszek-grzesiu')::uuid, 'zbyszek-grzesiu', md5('person:zbyszek')::uuid, md5('person:grzesiu')::uuid, 'znajomi', 55, 2019, null, 'Wspólne grzybobrania. Obaj twierdzą, że to ich miejscówka.', 'zabawna', 'confirmed', 'personal', md5('location:Działki')::uuid, 'published'),
