  (md5('relationship:krzysiek-ewka')::uuid, 'krzysiek-ewka', md5('person:krzysiek')::uuid, md5('person:ewka')::uuid, 'znajomi', 60, 2019, null, 'Ewka wciągnęła Krzyśka do ekipy. Nie żałuje. Chyba.', 'pozytywna', 'confirmed', 'personal', null, 'published'),
  (md5('relationship:krzysiek-grzesiu')::uuid, 'krzysiek-grzesiu', md5('person:krzysiek')::uuid, md5('person:grzesiu')::uuid, 'z-widzenia', 20, 2021, null, 'Mijają się na dworcu. Krzysiek zawsze pierwszy mówi „siema”.', 'neutralna', 'confirmed', 'personal', md5('location:Dworzec PKP')::uuid, 'published'),
