  (md5('relationship:rafal-lysy')::uuid, 'rafal-lysy', md5('person:rafal')::uuid, md5('person:lysy')::uuid, 'podobno', 25, 2020, null, 'Mówi się, że Łysy i Rafał mają „wspólne interesy”. Nikt nie wie jakie.', 'skomplikowana', 'rumor', 'personal', null, 'published'),
  (md5('relationship:dawid-magda')::uuid, 'dawid-magda', md5('person:dawid')::uuid, md5('person:magda')::uuid, 'imprezy', 35, 2021, null, 'Poznali się na urodzinach Ewki. Dawid podobno coś powiedział.', 'pozytywna', 'probable', 'personal', null, 'published'),
  (md5('relationship:seba-arek')::uuid, 'seba-arek', md5('person:seba')::uuid, md5('person:arek')::uuid, 'imprezy', 55, 2018, null, 'Wieczór nad Wisłą, po którym Seba stracił głos, a Arek klapek.', 'zabawna', 'confirmed', 'personal', md5('location:Nad Wisłą')::uuid, 'published'),
  (md5('relationship:darek-marek')::uuid, 'darek-marek', md5('person:darek')::uuid, md5('person:marek')::uuid, 'sasiedztwo', 60, 2016, null, 'Sąsiedzi przez ścianę. Darek wie, kiedy Marek wraca, po dźwięku kluczy.', 'zabawna', 'confirmed', 'personal', md5('location:Ławka pod blokiem')::uuid, 'published'),
  (md5('relationship:darek-arek')::uuid, 'darek-arek', md5('person:darek')::uuid, md5('person:arek')::uuid, 'biznes', 45, 2021, null, 'Wspólny „biznes” ze sprzedażą starych rowerów. Zarobili na jedną pizzę.', 'zabawna', 'confirmed', 'personal', null, 'published'),
