  (md5('relationship:bartek-krzychu')::uuid, 'bartek-krzychu', md5('person:bartek')::uuid, md5('person:krzychu')::uuid, 'sport', 50, 2017, null, 'Drużyna przeciwna w każdym meczu osiedlowym. Od lat 3:3 w bilansie.', 'zabawna', 'confirmed', 'personal', md5('location:Orlik przy szkole')::uuid, 'published'),
