  (md5('relationship:kamil-kuba')::uuid, 'kamil-kuba', md5('person:kamil')::uuid, md5('person:kuba')::uuid, 'sport', 50, 2020, null, 'Kamil trenuje Kubę na bramce. Kuba woli strzelać.', 'pozytywna', 'confirmed', 'personal', md5('location:Orlik przy szkole')::uuid, 'published'),
  (md5('relationship:ewka-damian')::uuid, 'ewka-damian', md5('person:ewka')::uuid, md5('person:damian')::uuid, 'znajomi', 40, 2017, null, 'Ewka pilnuje, żeby Damian wracał do domu o sensownej porze. Rzadko się udaje.', 'skomplikowana', 'confirmed', 'personal', null, 'published'),
  (md5('relationship:zbyszek-mariusz')::uuid, 'zbyszek-mariusz', md5('person:zbyszek')::uuid, md5('person:mariusz')::uuid, 'sasiedztwo', 35, 2016, null, 'Wujek Zbyszek mieszka piętro niżej i komentuje każdy trening Mariusza.', 'zabawna', 'confirmed', 'personal', null, 'published'),
  (md5('relationship:grzesiu-rafal')::uuid, 'grzesiu-rafal', md5('person:grzesiu')::uuid, md5('person:rafal')::uuid, 'inne', 30, 2021, null, 'Spotykają się tylko w lesie. Nikt nie wie, czy przypadkiem.', 'skomplikowana', 'lore', 'personal', md5('location:Działki')::uuid, 'published'),
  (md5('relationship:tomek-krzysiek')::uuid, 'tomek-krzysiek', md5('person:tomek')::uuid, md5('person:krzysiek')::uuid, 'praca', 40, 2022, null, 'Krzysiek pomógł Tomkowi przy przeprowadzce firmy. Za pizzę.', 'pozytywna', 'confirmed', 'personal', null, 'published'),
