  (md5('event:e-zbyszek-fontanna')::uuid, 'Pierwsza wzmianka o Wujku', 'Wujek Zbyszek po raz pierwszy opowiada o fontannie na rynku.', 2010, null, md5('location:Rynek')::uuid, 'confirmed', 'personal', 'published'),
  (md5('event:e-lysy-grzywka')::uuid, 'Ostatnie zdjęcie z grzywką', null, 2012, null, null, 'confirmed', 'personal', 'published'),
  (md5('event:e-krzychu-lysy-poznanie')::uuid, 'Początek duetu', 'Nikt nie wie, jak to się zaczęło. Wiadomo tylko, że było lato.', 2013, null, null, 'confirmed', 'personal', 'published'),
  (md5('event:e-krzychu-pod-blokiem')::uuid, 'Pierwszy raz widziany pod blokiem', 'Krzychu pojawia się na ławce i zostaje na dziesięć lat.', 2014, 5, md5('location:Ławka pod blokiem')::uuid, 'confirmed', 'personal', 'published'),
  (md5('event:e-marek-bartek-klasa')::uuid, 'Pierwszy dzień w klasie', 'Marek i Bartek siadają w różnych ławkach. Tak już zostaje.', 2014, 9, md5('location:Stara podstawówka')::uuid, 'confirmed', 'personal', 'published'),
  (md5('event:e-ewka-czat')::uuid, 'Powstaje grupowy czat', 'Ewka zakłada czat „Ekipa 🍺”. Nazwa zmieniała się 41 razy.', 2015, null, null, 'confirmed', 'personal', 'published'),
