  (md5('event:e-dworzec-akcja')::uuid, '„Szybka akcja” na dworcu', 'Miało być na chwilę. Skończyło się pierwszym porannym pociągiem.', 2016, 11, md5('location:Dworzec PKP')::uuid, 'confirmed', 'personal', 'published'),
  (md5('event:e-akcja-na-stacji')::uuid, 'Akcja na stacji', 'Marek i Arek opowiadają ją zupełnie inaczej. Obie wersje są zabawniejsze od prawdy.', 2017, 8, md5('location:Stacja paliw przy głównej')::uuid, 'confirmed', 'personal', 'published'),
  (md5('event:e-kebab')::uuid, 'Kolejka po kebaba', 'Damian i Seba stoją w kolejce 40 minut. Wychodzą jako kumple.', 2017, null, md5('location:Rynek')::uuid, 'confirmed', 'personal', 'published'),
  (md5('event:e-wisla-klapek')::uuid, 'Legendarny wieczór nad Wisłą', 'Seba traci głos, Arek klapek, a Damian — nie wiadomo co, ale coś na pewno.', 2018, 7, md5('location:Nad Wisłą')::uuid, 'confirmed', 'personal', 'published'),
  (md5('event:e-krzychu-damian')::uuid, 'Historia, której nie da się opowiedzieć', null, 2018, 8, md5('location:Nad Wisłą')::uuid, 'confirmed', 'personal', 'published'),
  (md5('event:e-profesor-quiz')::uuid, 'Profesor wygrywa quiz', 'Sam przeciwko czterem drużynom. Nagroda: skrzynka napojów, którą oddał.', 2018, null, null, 'confirmed', 'personal', 'published'),
  (md5('event:e-marek-krzysiek')::uuid, 'Marek poznaje Krzyśka', 'Na grillu u wspólnych znajomych. Krzysiek robi pierwsze zdjęcie grupowe.', 2019, 4, null, 'confirmed', 'personal', 'published'),
  (md5('event:e-kamil-karny')::uuid, 'Obroniony karny', 'Kamil broni karnego w meczu osiedlowym. Opowiada o tym co tydzień.', 2019, 6, null, 'confirmed', 'personal', 'published'),
  (md5('event:e-grzybobranie')::uuid, 'Wielkie grzybobranie', 'Zbyszek i Grzesiu idą w to samo miejsce. Obaj twierdzą, że pierwsi.', 2019, 9, md5('location:Działki')::uuid, 'confirmed', 'personal', 'published'),
  (md5('event:e-magazyn')::uuid, 'Pół roku na magazynie', null, 2020, null, null, 'confirmed', 'personal', 'published'),
  (md5('event:e-rafal-pojawia-sie')::uuid, 'Pojawia się Rafał', 'Nikt nie wie, kto go przyprowadził.', 2020, null, null, 'confirmed', 'personal', 'published'),
  (md5('event:e-urodziny-ewki')::uuid, 'Urodziny Ewki', 'Największa impreza roku. Magda robi 600 zdjęć, Dawid mówi coś, co wszyscy pamiętają.', 2021, 3, null, 'confirmed', 'personal', 'published'),
  (md5('event:e-tamta-noc')::uuid, 'Tamta noc', 'Podobno. Nic nie jest potwierdzone.', 2022, null, md5('location:Stacja paliw przy głównej')::uuid, 'confirmed', 'personal', 'published'),
  (md5('event:e-dawid-zdanie')::uuid, 'Jedno zdanie', 'Dawid mówi jedno zdanie. Od tej pory wszyscy je cytują.', 2022, null, null, 'confirmed', 'personal', 'published'),
  (md5('event:e-pralka')::uuid, 'Operacja „Pralka”', 'Mariusz wnosi pralkę na czwarte piętro. Łysy „koordynuje”.', 2023, null, md5('location:Ławka pod blokiem')::uuid, 'confirmed', 'personal', 'published'),
  (md5('event:e-marek-do-dzis')::uuid, 'Podobno do dziś…', '…Marek trzyma listę, kto komu ile oddał. Aktualizowana na bieżąco.', 2024, null, null, 'confirmed', 'personal', 'published'),
  (md5('event:e-10-lat-lawki')::uuid, '10 lat ławki', 'Jubileusz ławki pod blokiem. Obecni: prawie wszyscy.', 2025, null, md5('location:Ławka pod blokiem')::uuid, 'confirmed', 'personal', 'published'),
  (md5('event:e-legendarny-grill')::uuid, 'Legendarny grill', 'Wieczór, o którym do dziś krążą różne wersje historii.', 2019, 7, md5('location:Działki')::uuid, 'confirmed', 'personal', 'published'),
  (md5('event:e-rowery')::uuid, 'Biznes rowerowy', 'Darek i Arek sprzedają trzy rowery. Zarobek: jedna pizza, podzielona na pół.', 2021, null, null, 'confirmed', 'personal', 'draft')
