insert into public.lore (id, title, content, lore_type, year, confidence, source_type, status) values
  (md5('lore:l-fontanna')::uuid, 'Fontanna na rynku', 'Wujek Zbyszek twierdzi, że na rynku była kiedyś fontanna. Połowa ekipy mu wierzy, druga połowa sprawdza w internecie.', 'legenda', 2010, 'lore', 'personal', 'published'),
  (md5('lore:l-zdanie-dawida')::uuid, 'Zdanie Dawida', '„No i po co to było.” — jedyne zdanie Dawida z 2022 roku. Cytowane na każdej imprezie.', 'cytat', 2022, 'confirmed', 'personal', 'published'),
  (md5('lore:l-tamta-noc')::uuid, 'Tamta noc na stacji', 'Mówi się, że Arek i Dawid byli razem na stacji o trzeciej w nocy. Żaden z nich tego nie potwierdza.', 'plotka', 2022, 'rumor', 'personal', 'published'),
  (md5('lore:l-sztos')::uuid, 'Kto wymyślił „sztos”?', 'Seba twierdzi, że to on. Nikt nie ma dowodów ani przeciw, ani za.', 'inside-joke', null, 'lore', 'personal', 'published'),
  (md5('lore:l-grzywka')::uuid, 'Dwa zdjęcia z grzywką', 'Istnieją dokładnie dwa zdjęcia Łysego z grzywką. Magda ma oba i nie oddaje.', 'historia', 2016, 'confirmed', 'personal', 'published'),
  (md5('lore:l-klapek')::uuid, 'Klapek w Wiśle', 'Klapek Damiana (albo Arka — wersje się różnią) wciąż płynie gdzieś w stronę Bałtyku.', 'legenda', 2018, 'lore', 'personal', 'published'),
  (md5('lore:l-skrot')::uuid, 'Skrót przez pół miasta', 'Marek zna skrót, który rzekomo skraca drogę z dworca na rynek o połowę. Nikt nie zdążył go sprawdzić.', 'legenda', null, 'lore', 'personal', 'published'),
  (md5('lore:l-czat')::uuid, '41 nazw czatu', 'Grupowy czat Ewki zmieniał nazwę 41 razy. Obecna nazwa jest nieodpowiednia do publikacji.', 'ciekawostka', 2024, 'confirmed', 'personal', 'published'),
  (md5('lore:l-rafal-zajecie')::uuid, 'Czym zajmuje się Rafał?', 'Teorie: handel samochodami, IT, tajne służby, grzyby. Rafał tylko się uśmiecha.', 'plotka', null, 'rumor', 'personal', 'draft'),
  (md5('lore:l-karny')::uuid, 'Karny z 2019', 'Kamil obronił karnego w 2019. W jego wersji strzelał reprezentant Polski juniorów.', 'historia', 2019, 'probable', 'personal', 'published'),
  (md5('lore:l-grill')::uuid, 'Kto przyniósł węgiel?', 'Na legendarnym grillu nikt nie przyniósł węgla. Każdy do dziś twierdzi, że miał to zrobić ktoś inny.', 'inside-joke', 2019, 'lore', 'personal', 'published'),
  (md5('lore:l-wiertarka')::uuid, 'Wiertarka Darka', 'Wiertarka Darka odwiedziła każde mieszkanie w bloku. Wiertło — żadnego.', 'inside-joke', null, 'confirmed', 'personal', 'published'),
  (md5('lore:ff-marek-0')::uuid, null, 'Twierdzi, że zna skrót przez pół miasta.', 'ciekawostka', null, 'confirmed', 'personal', 'published'),
  (md5('lore:ff-marek-1')::uuid, null, 'Ma w telefonie kontakt zapisany jako „NIE ODBIERAĆ (chyba że piątek)”.', 'ciekawostka', null, 'confirmed', 'personal', 'published'),
  (md5('lore:ff-marek-2')::uuid, null, 'Jako jedyny pamięta, kto komu ile oddał.', 'ciekawostka', null, 'confirmed', 'personal', 'published'),
  (md5('lore:ff-krzychu-0')::uuid, null, 'Pojawia się na każdej większej imprezie.', 'ciekawostka', null, 'confirmed', 'personal', 'published'),
  (md5('lore:ff-krzychu-1')::uuid, null, 'Rower ma od 2009 roku i odmawia wymiany łańcucha.', 'ciekawostka', null, 'confirmed', 'personal', 'published'),
  (md5('lore:ff-krzysiek-0')::uuid, null, 'Zawsze robi zdjęcia grupowe, bo i tak wszystkich widzi z góry.', 'ciekawostka', null, 'confirmed', 'personal', 'published'),
  (md5('lore:ff-krzysiek-1')::uuid, null, 'Ma lęk przed gołębiami, o którym wszyscy wiedzą.', 'ciekawostka', null, 'confirmed', 'personal', 'published'),
  (md5('lore:ff-krzysztof-0')::uuid, null, 'Wygrał kiedyś quiz w pubie w pojedynkę przeciwko czterem drużynom.', 'ciekawostka', null, 'confirmed', 'personal', 'published'),
  (md5('lore:ff-krzysztof-1')::uuid, null, 'Nikt nie wie, czy naprawdę jest profesorem. Nikt nie pyta.', 'ciekawostka', null, 'confirmed', 'personal', 'published'),
  (md5('lore:ff-lysy-0')::uuid, null, 'Nikt nie wie, skąd ma ten numer.', 'ciekawostka', null, 'confirmed', 'personal', 'published'),
  (md5('lore:ff-lysy-1')::uuid, null, 'Ma teorię na każdy temat i dwie na temat pogody.', 'ciekawostka', null, 'confirmed', 'personal', 'published'),
  (md5('lore:ff-bartek-0')::uuid, null, 'Chodził z Markiem do jednej klasy przez 8 lat i siedział w innej ławce.', 'ciekawostka', null, 'confirmed', 'personal', 'published'),
  (md5('lore:ff-bartek-1')::uuid, null, 'Umie naprawić każdą zmywarkę, ale nie swoją.', 'ciekawostka', null, 'confirmed', 'personal', 'published'),
  (md5('lore:ff-arek-0')::uuid, null, 'Był świadkiem wydarzenia, o którym wszyscy mówią.', 'ciekawostka', null, 'confirmed', 'personal', 'published'),
  (md5('lore:ff-arek-1')::uuid, null, 'Ma kartę lojalnościową stacji paliw z najwyższym poziomem, a nie ma auta.', 'ciekawostka', null, 'confirmed', 'personal', 'published'),
  (md5('lore:ff-damian-0')::uuid, null, 'Zna na pamięć rozkład jazdy pociągów do Katowic.', 'ciekawostka', null, 'confirmed', 'personal', 'published'),
  (md5('lore:ff-damian-1')::uuid, null, 'Kiedyś zgubił klapek w Wiśle i do dziś szuka.', 'ciekawostka', null, 'confirmed', 'personal', 'published'),
  (md5('lore:ff-seba-0')::uuid, null, 'Jego głośnik bluetooth ma więcej znajomych niż on.', 'ciekawostka', null, 'confirmed', 'personal', 'published'),
  (md5('lore:ff-seba-1')::uuid, null, 'Twierdzi, że wymyślił słowo „sztos”.', 'ciekawostka', null, 'confirmed', 'personal', 'published'),
  (md5('lore:ff-kamil-0')::uuid, null, 'Obronił karnego w 2019 i opowiada o tym co tydzień.', 'ciekawostka', null, 'confirmed', 'personal', 'published'),
  (md5('lore:ff-tomek-0')::uuid, null, 'Ma trzy służbowe polary z trzech różnych firm.', 'ciekawostka', null, 'confirmed', 'personal', 'published'),
  (md5('lore:ff-tomek-1')::uuid, null, 'Zawsze ma przy sobie taśmę klejącą.', 'ciekawostka', null, 'confirmed', 'personal', 'published'),
  (md5('lore:ff-mariusz-0')::uuid, null, 'Wniósł kiedyś pralkę na czwarte piętro sam. Nie jego pralkę.', 'ciekawostka', null, 'confirmed', 'personal', 'published'),
  (md5('lore:ff-grzesiu-0')::uuid, null, 'Zna każde miejsce z kurkami w promieniu 20 km i nikomu nie powie.', 'ciekawostka', null, 'confirmed', 'personal', 'published'),
  (md5('lore:ff-zbyszek-0')::uuid, null, 'Zna wszystkich rodziców wszystkich osób na tej mapie.', 'ciekawostka', null, 'confirmed', 'personal', 'published'),
  (md5('lore:ff-zbyszek-1')::uuid, null, 'Ma zdanie na temat każdego remontu drogi od 1998 roku.', 'ciekawostka', null, 'confirmed', 'personal', 'published'),
  (md5('lore:ff-kuba-0')::uuid, null, 'Przez pierwsze dwa lata myślał, że Łysy ma na imię Łysy.', 'ciekawostka', null, 'confirmed', 'personal', 'published'),
  (md5('lore:ff-rafal-0')::uuid, null, 'Nikt nie wie, czym się zajmuje. Wszyscy mają swoją teorię.', 'ciekawostka', null, 'confirmed', 'personal', 'published'),
  (md5('lore:ff-ewka-0')::uuid, null, 'Prowadzi grupowy czat od 2016 roku i nigdy go nie wyciszyła.', 'ciekawostka', null, 'confirmed', 'personal', 'published'),
  (md5('lore:ff-ewka-1')::uuid, null, 'Organizuje wszystko. Dosłownie wszystko.', 'ciekawostka', null, 'confirmed', 'personal', 'published'),
  (md5('lore:ff-magda-0')::uuid, null, 'Jako jedyna ma zdjęcia z każdej imprezy. I nie oddaje.', 'ciekawostka', null, 'confirmed', 'personal', 'published'),
  (md5('lore:ff-dawid-0')::uuid, null, 'Powiedział w 2022 roku jedno zdanie, które wszyscy cytują.', 'ciekawostka', null, 'confirmed', 'personal', 'published'),
  (md5('lore:ff-darek-0')::uuid, null, 'Zawsze ma pożyczyć wiertarkę. Nigdy nie ma pożyczyć wiertła.', 'ciekawostka', null, 'confirmed', 'personal', 'published')
